  "registerstartupscript": "document.addEventListener('DOMContentLoaded', function() {
    var recurrenceTypeSelect = document.getElementById('new_recurrencetype');
    if (!recurrenceTypeSelect) {
        return;
    }

    if (typeof jQuery == 'undefined') {
        return;
    }

    var table = document.querySelector('table[data-name="tab_2_section_1"]');
    var recurrenceDaysContainer, recurrenceEndDateContainer;

    if (table) {
        recurrenceDaysContainer = table.querySelectorAll('tr')[5].querySelectorAll('td')[1];
        recurrenceEndDateContainer = table.querySelectorAll('tr')[4].querySelectorAll('td')[1];
    }

    if (!recurrenceDaysContainer || !recurrenceEndDateContainer) {
        console.error('Recurrence Days or End Date container not found');
        return;
    }

    var handleRecurrenceTypeChange = function() {
        var selectedValue = recurrenceTypeSelect.value;

        $(recurrenceDaysContainer).addClass('hidden');
        $(recurrenceEndDateContainer).addClass('hidden');

        SetFieldAsNonRequired('new_recurrencedays');
        SetFieldAsNonRequired('new_recurrenceenddate');

        // If 'Weekly' is selected, show the Recurrence Days and make it required
        if (selectedValue === '100000001') {
            $(recurrenceDaysContainer).removeClass('hidden');
            SetFieldAsRequired('new_recurrencedays', 'Recurrence Days');
            console.log('Recurrence Days container shown and marked as required.');
        }

        // For 'One Time' selection, hide the Recurrence End Date
        if (selectedValue === '100000003') {
            $(recurrenceEndDateContainer).addClass('hidden');
            SetFieldAsNonRequired('new_recurrenceenddate');
            console.log('Recurrence End Date container hidden for One Time selection.');
        } else {
            // For any non-empty selection other than 'One Time', show the Recurrence End Date and make it required
            $(recurrenceEndDateContainer).removeClass('hidden');
            SetFieldAsRequired('new_recurrenceenddate', 'Recurrence End Date');
            console.log('Recurrence End Date container shown and marked as required.');
        }
    };

    handleRecurrenceTypeChange();
    recurrenceTypeSelect.addEventListener('change', handleRecurrenceTypeChange);
});

function SetFieldAsRequired(fieldName, displayname)
{
    if (typeof (Page_Validators) == 'undefined') return;
    if ($("#" + fieldName) != undefined && $("#" + fieldName + "_label") != undefined)
    {
        $("#" + fieldName).prop('required', true);
        $("#" + fieldName).closest(".control").prev().addClass("required");
        // Create new validator object
        var Requiredvalidator = document.createElement('span');
        Requiredvalidator.style.display = "none";
        Requiredvalidator.id = fieldName + "Validator";
        Requiredvalidator.controltovalidate = fieldName;
        var errormessage = "<a href='#" + fieldName + "_label'>" +  displayname  + " is a required field.</a>";
        Requiredvalidator.errormessage = errormessage;
        Requiredvalidator.initialvalue = "";
        Requiredvalidator.evaluationfunction = function ()
        {
            var fieldControl = $("#" + fieldName);
            if (fieldControl.is("span"))
            {
                var value0 = $("#" + fieldName + "_0").prop("checked");
                var value1 = $("#" + fieldName + "_1").prop("checked");
                if (value0 == false && value1 == false)
                {
                    return false;
                }
                else
                {
                    return true;
                }
            }
            else
            {
                var value = $("#" + fieldName).val();
                if (value == null || value == "")
                {
                    return false;
                }
                else
                {
                    return true;
                }
            }
        };
        //Add the new validator to the page validators array
        Page_Validators.push(Requiredvalidator);
    }
}
function SetFieldAsNonRequired(fieldName)
{
    if (typeof (Page_Validators) == 'undefined') return;
    if ($("#" + fieldName) != undefined)
    {
        $("#" + fieldName).closest(".control").prev().removeClass("required");
        $("#" + fieldName).prop('required', false);
        for (i = 0; i < Page_Validators.length; i++)
        {
            if (Page_Validators[i].id == fieldName + "Validator")
            {
                Page_Validators.splice(i);
            }
        }
    }
}










